<?php

namespace App\Modules\Sessions\Attendance\Signing;

use App\Modules\Core\Audit\Auditable;
use App\Modules\Core\Tenancy\BelongsToTenant;
use Carbon\CarbonImmutable;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Carbon;

/**
 * An archived signed attendance sheet (table attendance_signed_sheets): the
 * PDF of a session for a Paris month, generated by SignedSheetPdf, never
 * overwritten (each generation is a new version), served from its archive
 * and checked against pdf_sha256.
 *
 * @property string $id
 * @property string $tenant_id
 * @property string $training_session_id
 * @property CarbonImmutable $month first day
 * @property string $path
 * @property string $pdf_sha256
 * @property string|null $generated_by
 * @property Carbon|null $created_at
 */
class SignedSheet extends Model
{
    use Auditable, BelongsToTenant, HasUuids;

    public const MORPH_ALIAS = 'attendance_signed_sheet';

    protected $table = 'attendance_signed_sheets';

    /** @var list<string> */
    protected array $auditIgnore = ['path'];

    /** @var list<string> */
    protected $fillable = ['training_session_id', 'month', 'path', 'pdf_sha256', 'generated_by'];

    protected function casts(): array
    {
        return ['month' => 'immutable_date'];
    }
}
